<?php declare(strict_types=1); namespace ProcessWire;
require __DIR__.'/support/bootstrap.php';
[$m,$db,$a,$b,$c]=fixture();
check($m->clientPolicy($a)['first_contact_mode']==='requests','default requests policy');
$m->set('max_message_length',7)->set('poll_thread_seconds',4)->set('poll_inbox_seconds',20)->set('max_pending_request_messages',2);
$p=$m->clientPolicy($a);check($p['max_message_length']===7&&$p['poll_thread_seconds']===4&&$p['poll_inbox_seconds']===20,'effective limits');
check($m->recipientContext($a,$b)===['conversation'=>null,'decision'=>'request'],'request context');
check((int)$db->query('SELECT COUNT(*) FROM messenger_conversations')->fetchColumn()===0,'lookup has no creation side effect');
$r=$m->startConversation($a,$b,'first','policy_first_0000001');$id=$r['conversation']['id'];
check($m->recipientContext($a,$b)['conversation']['id']===$id,'existing pending lookup');
check($m->conversation($id,$a)['can_send']&&!$m->conversation($id,$a)['can_attach'],'pending allowance without attachments');
check(!$m->conversation($id,$b)['can_send'],'recipient cannot send before acceptance');
$m->sendMessage($id,$a,'second','policy_second_00001');check(!$m->conversation($id,$a)['can_send'],'pending limit exhausted');
denied(fn()=>$m->sendMessage($id,$a,'third','policy_third_0000001'));
$m->acceptRequest($id,$b);check($m->conversation($id,$a)['can_send']&&$m->conversation($id,$a)['can_attach'],'accepted capabilities');
$m->set('edit_window_minutes',0)->set('delete_window_minutes',0);
$row=$m->conversationMessages($id,$a)[0];check(!$row['can_edit']&&!$row['can_delete_for_everyone'],'disabled edit/delete presentation');check(str_contains($row['created_at_iso'],'T'),'explicit ISO timestamp');
$m->set('edit_window_minutes',15)->set('delete_window_minutes',15);
$row=$m->conversationMessages($id,$a)[0];check($row['can_edit']&&$row['can_delete_for_everyone'],'eligible own message capabilities');
$row=$m->conversationMessages($id,$b)[0];check(!$row['can_edit']&&!$row['can_delete_for_everyone'],'peer cannot edit or remove own-only content');
$m->setArchived($id,$a,true);$m->set('first_contact_mode','closed');
check($m->recipientContext($a,$b)['conversation']['id']===$id,'archived accepted chat survives closed first contact');
check($m->recipientContext($a,$c)['decision']==='deny','new closed pair denied');
$m->hookAllow=true;check($m->recipientContext($a,$c)['decision']==='allow','trusted policy hook applied');
$db->exec('INSERT INTO messenger_blocks VALUES (11,22)');denied(fn()=>$m->recipientContext($a,$b));
$m->set('mobile_origin','');$m->services['config']->httpHosts=['example.test','alias.test'];$originAuth=new MessengerMobileAuth($m);
$_SERVER['HTTP_HOST']='attacker.test';check($originAuth->origin()==='https://example.test','issuer comes only from explicit httpHosts');
$m->services['config']->httpHosts=['EXAMPLE.TEST:443'];check($originAuth->origin()==='https://example.test','canonical host case and default port');
$m->services['config']->httpHosts=['*.example.test'];denied(fn()=>$originAuth->origin(),'configuration_unavailable');
$m->services['config']->httpHosts=[];denied(fn()=>$originAuth->origin(),'configuration_unavailable');
$m->set('mobile_origin','https://example.test');
$m->set('mobile_redirect_uris','');$auth=new MessengerMobileAuth($m);
$input=['redirect_uri'=>'org.smnv.narzan.dev://auth/callback','state'=>str_repeat('a',24),'code_challenge'=>str_repeat('b',43),'code_challenge_method'=>'S256'];
check($auth->authorizationRequest($input)['redirect_uri']===$input['redirect_uri'],'official callback works without configuration');
$bad=$input;$bad['redirect_uri']='org.attacker.app://auth/callback';denied(fn()=>$auth->authorizationRequest($bad),'invalid_redirect_uri');
$m->set('mobile_redirect_uris','org.custom.app://callback');denied(fn()=>$auth->authorizationRequest($input),'invalid_redirect_uri');
$bad['redirect_uri']='org.custom.app://callback';check($auth->authorizationRequest($bad)['redirect_uri']===$bad['redirect_uri'],'explicit custom override retains exact matching');
echo 'Client policy checks: '.$GLOBALS['checks'].PHP_EOL;
